from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    """Return x squared."""
    return x * x


def sum_squares(xs: list[int], *, max_workers: int | None = None) -> int:
    """Return the sum of the squares of every element of xs.

    The squares are computed in a thread pool with max_workers threads
    (None lets the executor choose). The result must be identical for
    every worker count. max_workers must be None or at least 1;
    otherwise ValueError is raised.
    """
    if max_workers is not None and max_workers < 1:
        raise ValueError(f"max_workers must be >= 1, got {max_workers}")
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        squares = pool.map(square, xs)
        return sum(squares)


def test_square() -> None:
    assert square(-3) == 9
    assert square(0) == 0
    assert square(7) == 49


def test_sum_squares_known_values() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([-4]) == 16


@pytest.mark.parametrize("workers", [None, 1, 2, 4, 8])
def test_sum_squares_matches_sequential(workers: int | None) -> None:
    xs = list(range(-50, 51))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, max_workers=workers) == expected


@pytest.mark.parametrize("workers", [None, 1, 3, 16])
def test_sum_squares_empty(workers: int | None) -> None:
    assert sum_squares([], max_workers=workers) == 0


def test_sum_squares_same_across_worker_counts() -> None:
    xs = [7, -3, 12, 0, 5, -9, 2] * 100
    results = {sum_squares(xs, max_workers=w) for w in (1, 2, 4, 8)}
    assert len(results) == 1


@pytest.mark.parametrize("workers", [0, -1])
def test_sum_squares_rejects_bad_worker_count(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2, 3], max_workers=workers)
